// Central config (fill tokens/keys after import)
return [{ json: {
  supabase: {
    url: "https://mdnthwpcnphjnnblbvxk.supabase.co",
    serviceKey: "PASTE_SERVICE_KEY"
  },
  r2: {
    bucket: "little-hero-orders",
    signedUrlEndpoint: "https://admin.littleherolabs.com/api/r2/signed-url",
    apiToken: "PASTE_BACKEND_API_TOKEN",
    expiresIn: 600,
    keyPrefix: "book-mvp-simple-adventure/orders",
    useBackendSignedUpload: true  // set false to use S3 node instead
  },
  s3: {
    endpoint: "https://ACCOUNTID.r2.cloudflarestorage.com",
    accessKeyId: "PASTE_R2_ACCESS_KEY_ID",
    secretAccessKey: "PASTE_R2_SECRET_ACCESS_KEY",
    accountId: "ACCOUNTID"
  }
} }];

// Normalize payload (paste a test order if needed)
const raw = $input.first()?.json || {
  amazonOrderId: 'TEST-ORDER-020',
  buyer: { name: 'Sample Buyer' },
  purchaseDate: new Date().toISOString(),
  items: [{
    sku: 'LHB-BOOK-STD',
    customizations: [{ name: 'Dedication', value: 'To Avery\nDream big!\nLove, Mom & Dad' }]
  }]
};

function extractItems(r){ return Array.isArray(r.items) ? r.items : (Array.isArray(r.lineItems) ? r.lineItems : []); }
function extractOrderId(r){ return r.amazonOrderId || r.orderId || r.id || 'UNKNOWN-ORDER'; }

return [{ json: {
  _raw: raw,
  orderId: extractOrderId(raw),
  items: extractItems(raw),
  buyer: raw.buyer || {},
  purchaseDate: raw.purchaseDate || raw.createdAt || null
}}];

// Extract & sanitize dedication
const norm = $input.first().json || {};

function fromItem(it){
  const fields = it.customizations || it.customizationFields || it.options || [];
  for (const f of (fields||[])){
    const name = (f.name||f.label||f.type||'').toLowerCase();
    if (name.includes('dedication') || name.includes('message') || name.includes('note')){
      const v = (f.value||f.text||f.stringValue||'')+'';
      if (v.trim()) return v;
    }
  }
  return null;
}

let found = null;
for (const li of (norm.items||[])){ if ((found = fromItem(li))) break; }
if (!found && norm._raw?.dedication) found = norm._raw.dedication;

// sanitize
const MAX_CHARS = 500, MAX_LINES = 6;
let t = ( (found || '') + '' )
  .replace(/[\u0000-\u0008\u000B-\u001F\u007F]/g,'')
  .replace(/\r\n?/g,'\n').replace(/[ \t]{2,}/g,' ');
t = t.split('\n').map(l => l.trimEnd()).join('\n').trim();
if (t.length > MAX_CHARS) t = t.slice(0, MAX_CHARS).trim();
t = t.split('\n').slice(0, MAX_LINES).join('\n');

const escape = s => s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

return [{ json: { ...norm,
  dedication: { raw: found || '', text: t, htmlSafe: escape(t) }
}}];

// Build 1-manifest.json and R2 key
const j = $input.first().json;
const r2Key = `book-mvp-simple-adventure/orders/${j.orderId}/manifests/1-manifest.json`;
const manifest = {
  schema: "lhb.run-manifest@v2.1",
  runStamp: new Date().toISOString(),
  amazonOrderId: j.orderId,
  order: { purchaseDate: j.purchaseDate || null, buyer: j.buyer || {} },
  dedication: j.dedication
};
return [{ json: { manifest, r2Key } }];

// Build fallback (no upload): just pass through r2Key and manifest
const { r2Key, manifest } = $input.first().json || {};
return [{ json: { r2Key, manifest } }];

// Upsert into Supabase orders with execution_status and one_manifest_url (we store KEY if URL not available)
const cfg = $item(0).$node["CONFIG (PRODUCTION)"].json;
const r2Key = $input.first().json.r2Key;
const manifest = $item(0).$node["Build 1‑manifest.json"].json.manifest;

const body = {
  amazon_order_id: manifest.amazonOrderId,
  execution_status: 'ready_for_processing',
  next_workflow: '3',
  one_manifest_url: r2Key, // store KEY; router will exchange for signed URL
  dedication_text: (manifest.dedication && manifest.dedication.text) || null,
  queued_at: new Date().toISOString()
};

const res = await this.helpers.request({
  method: 'POST',
  uri: `${cfg.supabase.url}/rest/v1/orders`,
  headers: {
    'apikey': cfg.supabase.serviceKey,
    'Authorization': `Bearer ${cfg.supabase.serviceKey}`,
    'Prefer': 'return=representation',
    'Content-Type': 'application/json'
  },
  body: JSON.stringify(body)
});

return [{ json: res }];
